-- AECI-1869: read-only. Counts profile.updated audit rows that still hold an About-you value.
-- Expect 0 after apply.sql. The six keys must match ABOUT_YOU_AUDIT_KEYS in apps/api/src/routes/account.ts.
SELECT count(*) AS rows_with_values FROM audit_log WHERE action = 'profile.updated' AND (json_type(before_state, '$.company_type') IS NOT NULL OR json_type(before_state, '$.company_size') IS NOT NULL OR json_type(before_state, '$.primary_role') IS NOT NULL OR json_type(before_state, '$.firm_name') IS NOT NULL OR json_type(before_state, '$.linkedin_url') IS NOT NULL OR json_type(before_state, '$.audience_ids') IS NOT NULL OR json_type(after_state, '$.company_type') IS NOT NULL OR json_type(after_state, '$.company_size') IS NOT NULL OR json_type(after_state, '$.primary_role') IS NOT NULL OR json_type(after_state, '$.firm_name') IS NOT NULL OR json_type(after_state, '$.linkedin_url') IS NOT NULL OR json_type(after_state, '$.audience_ids') IS NOT NULL);
